import{_ as r,o as e,c as t,a5 as o}from"./chunks/framework.bIR-4glx.js";const u=JSON.parse('{"title":"AI 趋势实验卡：从信号到决定","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/ai-trend-radar.zh.md","filePath":"public/downloads/worksheets/ai-trend-radar.zh.md","lastUpdated":1795488252000}'),n={name:"public/downloads/worksheets/ai-trend-radar.zh.md"};function i(d,a,h,l,b,s){return e(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="ai-趋势实验卡-从信号到决定" tabindex="-1">AI 趋势实验卡：从信号到决定 <a class="header-anchor" href="#ai-趋势实验卡-从信号到决定" aria-label="Permalink to &quot;AI 趋势实验卡：从信号到决定&quot;">​</a></h1><p>每次只测试一个变化。它不是产品收藏夹，也不是预测榜单；它帮助你判断一个能力是否值得进入自己的任务。没有人工基线、可检查的结果和停止条件，就先不要扩大范围。</p><h2 id="可复制记录" tabindex="-1">可复制记录 <a class="header-anchor" href="#可复制记录" aria-label="Permalink to &quot;可复制记录&quot;">​</a></h2><h3 id="ai-trend-radar-yyyy-mm-dd" tabindex="-1">AI Trend Radar - YYYY-MM-DD <a class="header-anchor" href="#ai-trend-radar-yyyy-mm-dd" aria-label="Permalink to &quot;AI Trend Radar - YYYY-MM-DD&quot;">​</a></h3><h4 id="_1-信号与证据" tabindex="-1">1. 信号与证据 <a class="header-anchor" href="#_1-信号与证据" aria-label="Permalink to &quot;1. 信号与证据&quot;">​</a></h4><p>趋势或能力：<br> 一手来源、发布日期/版本、访问日期：<br> 来源明确观察到什么：<br> 我的条件判断或未来假设：<br> 仍然未知、可能过期或不能从来源推出的内容：</p><h4 id="_2-真实任务" tabindex="-1">2. 真实任务 <a class="header-anchor" href="#_2-真实任务" aria-label="Permalink to &quot;2. 真实任务&quot;">​</a></h4><p>使用者、场景和要完成的动作：<br> 当前瓶颈：<br> 不使用新能力的人工基线位置、时间和质量：<br> 不适用的任务或输入：</p><h4 id="_3-最小实验" tabindex="-1">3. 最小实验 <a class="header-anchor" href="#_3-最小实验" aria-label="Permalink to &quot;3. 最小实验&quot;">​</a></h4><p>本轮只改变：<br> 模型、版本、地区、提示、材料、记忆和工具：<br> 允许的输入模态：文字 / 音频 / 图片 / 视频 / 混合<br> 数据、版权、隐私和权限边界：<br> 允许的自动化级别：只读 / 草稿 / 可撤销动作 / 不可逆动作（需批准）<br> 正常、缺项、冲突、过期、失败和提示注入案例：<br> 开发集 / 未参与调优的保留集：</p><h4 id="_4-证据与成本" tabindex="-1">4. 证据与成本 <a class="header-anchor" href="#_4-证据与成本" aria-label="Permalink to &quot;4. 证据与成本&quot;">​</a></h4><p>AI 样本位置：<br> 任务/运行编号、过程轨迹和检查点位置：<br> 干净环境、网络出口白名单、凭证范围与页面/链接不可信输入说明：<br> 工具调用、授权和最终环境状态位置：<br> 独立样本（关闭 AI）位置：<br> 平行任务（换主题/受众/模态/工具）位置：<br> 首次合格 / 人工修订后合格：<br> 总时间：准备 / 运行 / 核验 / 返工 / 维护：<br> 工具费用、设备资源和人工时间估值：<br> 来源、识别、事实、权限和安全失败：</p><h4 id="_5-决定与退出" tabindex="-1">5. 决定与退出 <a class="header-anchor" href="#_5-决定与退出" aria-label="Permalink to &quot;5. 决定与退出&quot;">​</a></h4><p>硬门是否全部通过，证据在哪里：<br> 继续 / 降档 / 停止：<br> 允许范围与人工接管条件：<br> 模型、资料、工具或记忆变化后的复测触发：<br> 可恢复版本、断开工具或手工退路：<br> 供应商政策/版本、生效日期、地区和高风险人工复核：<br> 独立复核人、复核方式和可发表的证据位置：<br> 切换供应商或换会话后能否继续：<br> 负责人和 30 天复查日期：</p><h2 id="判定顺序" tabindex="-1">判定顺序 <a class="header-anchor" href="#判定顺序" aria-label="Permalink to &quot;判定顺序&quot;">​</a></h2><p>先看来源与权限，再看事实和任务结果，最后比较速度、文风或费用。把识别错误与知识错误分开；把模型声称完成与文件、数据库或真实读者看到的结果分开。保留集一旦用于调优，就把它移入开发或回归集，并补充新的保留案例。</p><h2 id="关联入口" tabindex="-1">关联入口 <a class="header-anchor" href="#关联入口" aria-label="Permalink to &quot;关联入口&quot;">​</a></h2><p><a href="https://byoungd.github.io/up/threads/part-3/6-ai-trends-and-learning-roadmap" target="_blank" rel="noreferrer">AI 趋势与学习路线</a> ｜ <a href="https://byoungd.github.io/up/templates/ai-task-brief" target="_blank" rel="noreferrer">AI 任务简报</a> ｜ <a href="https://byoungd.github.io/up/templates/ai-learning-log" target="_blank" rel="noreferrer">AI 学习记录</a> ｜ <a href="https://byoungd.github.io/up/templates/ai-evaluation" target="_blank" rel="noreferrer">AI 评测记录</a></p><hr><p>来源：<a href="https://byoungd.github.io/up/templates/ai-trend-radar" target="_blank" rel="noreferrer">人生进阶指南</a> · 稿件更新：2026-10-16。内容许可：<a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>。</p>',20)])])}const c=r(n,[["render",i]]);export{u as __pageData,c as default};
